#!/usr/bin/env node
/**
 * Tests for scripts/gate.mjs: the test command under a stuck check, the wait cap, the scope check, the
 * unchanged-tree skip, the format-only list and the red proof. Each case runs in its own temp git repository;
 * the commands are tiny `node -e` programs, and the minutes are fractions so every case takes seconds.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath, pathToFileURL } from 'node:url';

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'scripts', 'gate.mjs');
const OK = 'node -e "process.exit(0)"';
const FAIL = 'node -e "process.exit(1)"';
const STAMP = 'node -e "console.log(Date.now())"'; // a run leaves a fresh stamp in the log, a skip leaves it alone
const STUCK = 'node -e "console.log(\'start\');setInterval(()=>{},1000)"';
const SLOW = 'node -e "console.log(\'start\');let n=0;const t=setInterval(()=>{console.log(\'tick\');if(++n>=25)clearInterval(t)},100)"';
const created = [];

process.on('exit', () => {
  for (const dir of created) {
    try { rmSync(dir, { recursive: true, force: true }); } catch { /* tmp, let the OS have it */ }
  }
});

const git = (root, ...args) => spawnSync('git', ['-c', 'user.name=t', '-c', 'user.email=t@t', ...args], { cwd: root, encoding: 'utf8' }).stdout.trim();

/** A temp git repository with one commit and an active perimeter of `entries` (none: no perimeter file): `{ root, head }`. */
function repo(entries = ['**']) {
  const root = mkdtempSync(join(tmpdir(), 'gate-'));
  created.push(root);
  git(root, 'init');
  writeFileSync(join(root, 'README.md'), 'hello\n');
  git(root, 'add', '-A');
  git(root, 'commit', '-m', 'init');
  if (entries) {
    const dir = join(root, '.git', 'deliver');
    mkdirSync(dir, { recursive: true });
    const branch = git(root, 'rev-parse', '--abbrev-ref', 'HEAD');
    writeFileSync(join(dir, 'perimeter.md'), `branch: ${branch}\nstatus: active\n${entries.map((e) => `- ${e}`).join('\n')}\n`);
  }
  return { root, head: git(root, 'rev-parse', 'HEAD') };
}

const logOf = (r) => readFileSync(join(r.root, '.git', 'deliver', 'gate.log'), 'utf8');

// NODE_TEST_CONTEXT would make the `node --test` the gate runs report into this run instead of printing its own
const { NODE_TEST_CONTEXT, ...env } = process.env;
const gate = (root, ...args) => spawnSync(process.execPath, [SCRIPT, '--root', root, ...args], { encoding: 'utf8', env });
const run = (r, command, ...args) => gate(r.root, '--head', r.head, '--test', command, ...args);
const KEYS = ['gate', 'test', 'outside', 'formatOnly', 'tree', 'greenAt', 'seconds'].sort();
const lastLine = (res) => {
  const out = JSON.parse(res.stdout.trim().split(/\r?\n/).pop());
  assert.deepEqual(Object.keys(out).sort(), KEYS);
  return out;
};
const stateOf = (r) => JSON.parse(readFileSync(join(r.root, '.git', 'deliver', 'gate.json'), 'utf8'));
const { failedTests } = await import(pathToFileURL(SCRIPT).href);

const UNIT = 'node --test t.test.mjs';
const TEST_SOURCE = [
  "import { test } from 'node:test';",
  "import assert from 'node:assert/strict';",
  "import { existsSync } from 'node:fs';",
  "test('needs the flag file', () => assert.ok(existsSync(new URL('./flag.txt', import.meta.url))));",
  '',
].join('\n');

/** A repo holding one test file that passes only once `flag.txt` exists. */
function repoWithTest(flag = false) {
  const r = repo();
  writeFileSync(join(r.root, 't.test.mjs'), TEST_SOURCE);
  if (flag) writeFileSync(join(r.root, 'flag.txt'), 'x\n');
  return r;
}

const red = (r, unit = UNIT) => gate(r.root, '--red', '--unit', unit, '--test-files', 't.test.mjs');

test('given dotnet output with a failed test, when the failures are read, then the test name is listed and the summary line is not', () => {
  // Given
  const log = '  Passed Calc.Subtracts [1 ms]\n  Failed Calc.Adds [12 ms]\n  Error Message: x\nFailed!  - Failed: 1, Passed: 1\n';

  // When
  const names = failedTests(log);

  // Then
  assert.deepEqual(names, ['Calc.Adds']);
});

test('given node spec output, when the failures are read, then each failed test is listed once and "failing tests:" is not', () => {
  // Given
  const log = '✔ fine (1.2ms)\n✖ adds (2.5ms)\nℹ fail 1\n✖ failing tests:\n\n✖ adds (2.5ms)\n';

  // When
  const names = failedTests(log);

  // Then
  assert.deepEqual(names, ['adds']);
});

test('given node TAP output where a file failed to load, when the failures are read, then the file is no test and a real failure stays', () => {
  // Given
  const log = 'TAP version 13\nnot ok 1 - C:\\repo\\t.test.mjs\nnot ok 2 - src/other.mjs\nnot ok 3 - adds\n';

  // When
  const withFiles = failedTests(log, ['src/other.mjs']);
  const loadOnly = failedTests('not ok 1 - C:\\repo\\t.test.mjs\n');

  // Then
  assert.deepEqual(withFiles, ['adds']);
  assert.deepEqual(loadOnly, []);
});

test('given vitest output, when the failures are read, then the FAIL and × lines name the test and a file-level FAIL is no test', () => {
  // Given
  const log = ' ❯ src/a.test.ts (1 test | 1 failed)\n   × adds 3ms\n FAIL  src/a.test.ts > adds\nAssertionError\n FAIL  src/b.test.ts [ src/b.test.ts ]\n';

  // When
  const names = failedTests(log);

  // Then
  assert.deepEqual(names, ['adds']);
});

test('given jest output, when the failures are read, then only a "suite › test" line counts, not Console or "Test suite failed to run"', () => {
  // Given
  const log = ' FAIL src/a.test.js\n  ● Console\n\n  ● Math › adds\n\n  ● Test suite failed to run\n';

  // When
  const names = failedTests(log);
  const suiteOnly = failedTests(' FAIL src/b.test.js\n  ● Test suite failed to run\n');

  // Then
  assert.deepEqual(names, ['Math › adds']);
  assert.deepEqual(suiteOnly, []);
});

test("given a runner the gate can't read, when it runs with --red, then it exits 2", () => {
  // Given
  const r = repoWithTest();

  // When
  const res = red(r, FAIL);

  // Then
  assert.equal(res.status, 2);
  assert.ok(!res.stdout.includes('red-proven'));
});

// ── lanes: --lane-add and --merge ─────────────────────────────────────────────
const laneAdd = (r, name) => {
  const res = gate(r.root, '--head', r.head, '--lane-add', name);
  assert.equal(res.status, 0, res.stderr);
  const lane = JSON.parse(res.stdout.trim().split(/\r?\n/).pop());
  created.push(lane.path);
  return lane;
};
const lf = (path) => readFileSync(path, 'utf8').replace(/\r\n/g, '\n'); // autocrlf checkouts write CRLF
const mergeRun = (r, refs, command = OK) => gate(r.root, '--head', r.head, '--test', command, '--merge', ...refs);
const refs = (lanes) => lanes.map((l) => l.branch);

test('given a start head, when a lane is added, then a worktree and a branch exist from that head and the perimeter follows the lane branch', () => {
  // Given
  const r = repo(['src/**']);

  // When
  const lane = laneAdd(r, 'l1');

  // Then
  assert.equal(lane.branch, 'deliver-lane/l1');
  assert.equal(git(lane.path, 'rev-parse', 'HEAD'), r.head);
  assert.equal(git(lane.path, 'rev-parse', '--abbrev-ref', 'HEAD'), 'deliver-lane/l1');
  const laneGitDir = git(lane.path, 'rev-parse', '--absolute-git-dir');
  const perimeter = readFileSync(join(laneGitDir, 'deliver', 'perimeter.md'), 'utf8');
  assert.match(perimeter, /^branch: deliver-lane\/l1$/m);
  assert.match(perimeter, /^- src\/\*\*$/m);
});

test('given a lane name already taken, when a lane is added, then the next free name is used', () => {
  // Given
  const r = repo();
  const first = laneAdd(r, 'l1');

  // When
  const second = laneAdd(r, 'l1');

  // Then
  assert.notEqual(second.branch, first.branch);
  assert.notEqual(second.path, first.path);
});

test('given two lane branches that edit different files, when the merge gate runs, then both changes are in the start tree, the tests run green and the lanes are gone', () => {
  // Given
  const r = repo();
  const lanes = [laneAdd(r, 'l1'), laneAdd(r, 'l2')];
  writeFileSync(join(lanes[0].path, 'one.txt'), 'one\n');
  writeFileSync(join(lanes[1].path, 'two.txt'), 'two\n');

  // When
  const res = mergeRun(r, refs(lanes));

  // Then
  assert.equal(lastLine(res).gate, 'green');
  assert.equal(res.status, 0);
  assert.equal(lf(join(r.root, 'one.txt')), 'one\n');
  assert.equal(lf(join(r.root, 'two.txt')), 'two\n');
  assert.equal(git(r.root, 'rev-parse', 'HEAD'), r.head);
  assert.ok(!existsSync(lanes[0].path) && !existsSync(lanes[1].path));
  assert.equal(git(r.root, 'branch', '--list', 'deliver-lane/*'), '');
});

test('given two lane branches that conflict, when the merge gate runs, then the merge is aborted and reported as red: merge', () => {
  // Given
  const r = repo();
  const lanes = [laneAdd(r, 'l1'), laneAdd(r, 'l2')];
  writeFileSync(join(lanes[0].path, 'README.md'), 'from lane one\n');
  writeFileSync(join(lanes[1].path, 'README.md'), 'from lane two\n');

  // When
  const res = mergeRun(r, refs(lanes), STAMP);

  // Then
  const out = lastLine(res);
  assert.equal(out.gate, 'red: merge');
  assert.deepEqual(out.outside, ['README.md']);
  assert.equal(res.status, 1);
  assert.equal(git(r.root, 'rev-parse', 'HEAD'), r.head);
  assert.equal(git(r.root, 'status', '--porcelain'), '');
  assert.ok(!existsSync(join(r.root, '.git', 'MERGE_HEAD')));
  assert.equal(lf(join(r.root, 'README.md')), 'hello\n');
  assert.equal(git(r.root, 'branch', '--list', 'deliver-lane/*').split('\n').length, 2);
});

test('given a first lane that merges and a second that conflicts, when the merge gate runs, then the start branch is back at its head with no lane change left', () => {
  // Given
  const r = repo();
  const lanes = [laneAdd(r, 'l1'), laneAdd(r, 'l2'), laneAdd(r, 'l3')];
  writeFileSync(join(lanes[0].path, 'one.txt'), 'one\n');
  writeFileSync(join(lanes[1].path, 'README.md'), 'from lane two\n');
  writeFileSync(join(lanes[2].path, 'README.md'), 'from lane three\n');

  // When
  const res = mergeRun(r, refs(lanes));

  // Then
  assert.equal(lastLine(res).gate, 'red: merge');
  assert.equal(git(r.root, 'rev-parse', 'HEAD'), r.head);
  assert.equal(git(r.root, 'status', '--porcelain'), '');
});

test('given a ref that starts with a dash or is unknown, when the merge gate runs, then it exits 2 and merges nothing', () => {
  // Given
  const r = repo();
  const lane = laneAdd(r, 'l1');
  writeFileSync(join(lane.path, 'one.txt'), 'one\n');

  // When
  const dashed = mergeRun(r, [lane.branch, '-x']);
  const unknown = mergeRun(r, [lane.branch, 'deliver-lane/nope']);

  // Then
  assert.equal(dashed.status, 2);
  assert.equal(unknown.status, 2);
  assert.ok(!existsSync(join(r.root, 'one.txt')));
  assert.ok(existsSync(lane.path));
});

const lastRaw = (res) => JSON.parse(res.stdout.trim().split(/\r?\n/).pop());

test('given a staged file in the start tree, when the merge gate runs, then it exits 2 and leaves the index, the head and the lane as they were', () => {
  // Given
  const r = repo();
  const lane = laneAdd(r, 'l1');
  writeFileSync(join(lane.path, 'one.txt'), 'one\n');
  writeFileSync(join(r.root, 'staged.txt'), 'mine\n');
  git(r.root, 'add', 'staged.txt');

  // When
  const res = mergeRun(r, [lane.branch]);

  // Then
  assert.equal(res.status, 2);
  assert.match(res.stderr, /staged/);
  assert.equal(git(r.root, 'diff', '--cached', '--name-only'), 'staged.txt');
  assert.equal(git(r.root, 'rev-parse', 'HEAD'), r.head);
  assert.ok(!existsSync(join(r.root, 'one.txt')));
  assert.ok(existsSync(lane.path));
  assert.equal(git(r.root, 'rev-parse', lane.branch), r.head);
});

test('given a modified file in the start tree that a lane also changes, when the merge gate runs, then it exits 2 and touches nothing', () => {
  // Given
  const r = repo();
  const lane = laneAdd(r, 'l1');
  writeFileSync(join(lane.path, 'README.md'), 'from the lane\n');
  writeFileSync(join(r.root, 'README.md'), 'the user edit\n');

  // When
  const res = mergeRun(r, [lane.branch]);

  // Then
  assert.equal(res.status, 2);
  assert.match(res.stderr, /README\.md/);
  assert.equal(lf(join(r.root, 'README.md')), 'the user edit\n');
  assert.equal(git(r.root, 'rev-parse', lane.branch), r.head);
  assert.ok(existsSync(lane.path));
});

test('given an untracked file in the start tree that a lane also adds, when the merge gate runs, then it exits 2 and touches nothing', () => {
  // Given
  const r = repo();
  const lane = laneAdd(r, 'l1');
  writeFileSync(join(lane.path, 'new.txt'), 'from the lane\n');
  writeFileSync(join(r.root, 'new.txt'), 'the user file\n');

  // When
  const res = mergeRun(r, [lane.branch]);

  // Then
  assert.equal(res.status, 2);
  assert.match(res.stderr, /new\.txt/);
  assert.equal(lf(join(r.root, 'new.txt')), 'the user file\n');
  assert.ok(existsSync(lane.path));
});

test('given a modified file in the start tree that no lane changes, when the merge gate runs, then the lane merges and the user edit stays', () => {
  // Given
  const r = repo();
  const lane = laneAdd(r, 'l1');
  writeFileSync(join(lane.path, 'one.txt'), 'one\n');
  writeFileSync(join(r.root, 'README.md'), 'the user edit\n');

  // When
  const res = mergeRun(r, [lane.branch]);

  // Then
  assert.equal(lastLine(res).gate, 'green');
  assert.equal(lf(join(r.root, 'README.md')), 'the user edit\n');
  assert.equal(lf(join(r.root, 'one.txt')), 'one\n');
});

test('given an existing branch without the deliver-lane/ prefix, when the merge gate runs, then it exits 2 and merges nothing', () => {
  // Given
  const r = repo();
  git(r.root, 'branch', 'other');

  // When
  const res = mergeRun(r, ['other']);

  // Then
  assert.equal(res.status, 2);
  assert.match(res.stderr, /deliver-lane\//);
});

test('given a conflict, when the merge gate answers red: merge, then the lane worktrees and branches are kept', () => {
  // Given
  const r = repo();
  const lanes = [laneAdd(r, 'l1'), laneAdd(r, 'l2')];
  writeFileSync(join(lanes[0].path, 'README.md'), 'from lane one\n');
  writeFileSync(join(lanes[1].path, 'README.md'), 'from lane two\n');

  // When
  const res = mergeRun(r, refs(lanes));

  // Then
  assert.equal(lastLine(res).gate, 'red: merge');
  assert.ok(existsSync(lanes[0].path) && existsSync(lanes[1].path));
  assert.equal(git(r.root, 'branch', '--list', 'deliver-lane/*').split('\n').length, 2);
});

test('given a merged lane whose worktree is locked, when the merge gate runs, then the last line lists the worktree and the branch in leftover', () => {
  // Given
  const r = repo();
  const lane = laneAdd(r, 'l1');
  writeFileSync(join(lane.path, 'one.txt'), 'one\n');
  git(r.root, 'worktree', 'lock', lane.path);

  // When
  const res = mergeRun(r, [lane.branch]);

  // Then
  const out = lastRaw(res);
  assert.equal(out.gate, 'green');
  assert.equal(out.leftover.length, 2);
  assert.match(out.leftover[0], /^worktree /);
  assert.match(out.leftover[1], /^branch deliver-lane\/l1/);
  git(r.root, 'worktree', 'unlock', lane.path);
});

test('given two lanes, when they are removed with --lane-remove, then each worktree and branch is gone and each is reported', () => {
  // Given
  const r = repo();
  const lanes = [laneAdd(r, 'l1'), laneAdd(r, 'l2')];
  writeFileSync(join(lanes[0].path, 'one.txt'), 'unsaved\n');

  // When
  const res = gate(r.root, '--lane-remove', ...refs(lanes));

  // Then
  assert.equal(res.status, 0, res.stderr);
  const { removed } = lastRaw(res);
  assert.deepEqual(removed.map((x) => [x.branch, x.ok]), refs(lanes).map((b) => [b, true]));
  assert.ok(!existsSync(lanes[0].path) && !existsSync(lanes[1].path));
  assert.equal(git(r.root, 'branch', '--list', 'deliver-lane/*'), '');
});

test('given a branch outside deliver-lane/, when --lane-remove runs, then it exits 2 and the branch stays', () => {
  // Given
  const r = repo();
  git(r.root, 'branch', 'other');

  // When
  const res = gate(r.root, '--lane-remove', 'other');

  // Then
  assert.equal(res.status, 2);
  assert.equal(git(r.root, 'branch', '--list', 'other').trim(), 'other');
});

// ── --accept-tests: an edit of a proven test file that the plan lists is no longer red: tests changed ─────
const UNIT2 = 'node --test t.test.mjs t2.test.mjs';

/** A repo with two test files proven red; `flag.txt` is not there yet when `flag` is false. */
function repoWithTwoProven(flag = true) {
  const r = repoWithTest();
  writeFileSync(join(r.root, 't2.test.mjs'), TEST_SOURCE.replace('needs the flag file', 'second needs the flag file'));
  gate(r.root, '--red', '--unit', UNIT2, '--test-files', 't.test.mjs,t2.test.mjs');
  if (flag) writeFileSync(join(r.root, 'flag.txt'), 'x\n');
  return r;
}

test('given a stored proof and a changed proven file listed in --accept-tests, when the gate runs, then it is green, the file leaves the proof and the last line lists it in testsAccepted', () => {
  // Given
  const r = repoWithTwoProven();
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited by the plan\n`);

  // When
  const res = run(r, UNIT2, '--accept-tests', 't.test.mjs');

  // Then
  assert.equal(res.status, 0);
  assert.equal(lastRaw(res).gate, 'green');
  assert.deepEqual(lastRaw(res).testsAccepted, ['t.test.mjs']);
});

test('given a changed proven file that is not listed in --accept-tests, when the gate runs, then it reports red: tests changed naming only the unlisted file', () => {
  // Given
  const r = repoWithTwoProven();
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited by the plan\n`);
  writeFileSync(join(r.root, 't2.test.mjs'), `${TEST_SOURCE}// weakened\n`);

  // When
  const res = run(r, UNIT2, '--accept-tests', 't.test.mjs');

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastRaw(res).gate, 'red: tests changed');
  assert.equal(lastRaw(res).test, 't2.test.mjs');
});

test('given a changed proven file and no --accept-tests, when the gate runs, then it reports red: tests changed and the last line has no testsAccepted', () => {
  // Given
  const r = repoWithTwoProven();
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited\n`);

  // When
  const res = run(r, UNIT2);

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastRaw(res).gate, 'red: tests changed');
  assert.equal('testsAccepted' in lastRaw(res), false);
});

test('given the only proven file accepted and the tests still failing, when the gate runs, then the proof is gone from gate.json', () => {
  // Given
  const r = repoWithTest();
  red(r);
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited by the plan\n`);

  // When
  const res = run(r, UNIT, '--accept-tests', 't.test.mjs');

  // Then
  assert.equal(lastRaw(res).gate, 'red');
  assert.equal(stateOf(r).proof, undefined);
});

test('given one of two proven files accepted and the tests still failing, when the gate runs, then only the other file stays in the proof', () => {
  // Given
  const r = repoWithTwoProven(false);
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited by the plan\n`);

  // When
  const res = run(r, UNIT2, '--accept-tests', 't.test.mjs');

  // Then
  assert.equal(lastRaw(res).gate, 'red');
  assert.deepEqual(Object.keys(stateOf(r).proof.files), ['t2.test.mjs']);
});

test('given an accepted proven edit and a scope violation, when the gate runs, then red: scope still lists testsAccepted and a rerun carries it until green', () => {
  // Given
  const r = repoWithTwoProven();
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited by the plan\n`);
  writeFileSync(join(r.root, 'other.txt'), 'x\n');
  const branch = git(r.root, 'rev-parse', '--abbrev-ref', 'HEAD');
  writeFileSync(join(r.root, '.git', 'deliver', 'perimeter.md'), `branch: ${branch}\nstatus: active\n- t.test.mjs\n- t2.test.mjs\n- flag.txt\n`);

  // When
  const first =run(r, UNIT2, '--accept-tests', 't.test.mjs',);
  const second = run(r, UNIT2, '--accept-tests', 't.test.mjs',);

  // Then
  assert.equal(lastRaw(first).gate, 'red: scope');
  assert.deepEqual(lastRaw(first).testsAccepted, ['t.test.mjs']);
  assert.deepEqual(lastRaw(second).testsAccepted, ['t.test.mjs']);
});

test('given an accepted proven edit that went green, when the gate runs again, then the last line still lists testsAccepted', () => {
  // Given
  const r = repoWithTwoProven();
  writeFileSync(join(r.root, 't.test.mjs'), `${TEST_SOURCE}// edited by the plan\n`);
  const first = run(r, UNIT2, '--accept-tests', 't.test.mjs');

  // When
  const second = run(r, UNIT2);

  // Then
  assert.equal(lastRaw(first).gate, 'green');
  assert.equal(lastRaw(second).gate, 'skipped: tree unchanged');
  assert.deepEqual(lastRaw(second).testsAccepted, ['t.test.mjs']);
});

test('given a test file proven red by a --red --probe and listed in --accept-tests, when the gate runs after it is edited, then it is red: tests changed, not accepted', () => {
  // Given
  const r = repoWithTest();
  red(r);
  writeFileSync(join(r.root, 'p.test.mjs'), TEST_SOURCE.replace('needs the flag file', 'probe needs the flag file'));
  gate(r.root, '--red', '--probe', '--unit', 'node --test p.test.mjs', '--test-files', 'p.test.mjs');
  writeFileSync(join(r.root, 'p.test.mjs'), `${TEST_SOURCE}// edited by the plan\n`);

  // When
  const res = run(r, 'node --test p.test.mjs', '--accept-tests', 'p.test.mjs');

  // Then
  assert.equal(res.status, 1);
  assert.equal(lastRaw(res).gate, 'red: tests changed');
  assert.equal(lastRaw(res).test, 'p.test.mjs');
  assert.equal('testsAccepted' in lastRaw(res), false);
});
